    const industry=String(config.industry||'').slice(0,100),location=String(config.location||'').slice(0,120),keywords=String(config.keywords||'').slice(0,180),targetAudience=String(config.targetAudience||'').slice(0,1200),maxResults=Math.max(5,Math.min(50,Number(config.maxResults)||20));
