export async function GET(req:NextRequest){const secret=process.env.CRON_SECRET;if(!secret||req.headers.get('authorization')!==`Bearer ${secret}`)return json({error:'Unauthorized worker request.'},401);const url=process.env.NEXT_PUBLIC_SUPABASE_URL,key=process.env.SUPABASE_SERVICE_ROLE_KEY;if(!url||!key)return json({error:'Database worker is not configured.'},503);const db=createClient(url,key,{auth:{persistSession:false}});let autonomousSchedules:any[]=[];try{autonomousSchedules=await runAutonomousSchedules(db);}catch(e){autonomousSchedules=[{status:'error',error:e instanceof Error?e.message:'Autonomous schedule runner failed'}];}const {data:jobs,error}=await db.rpc('claim_growth_jobs',{batch_limit:10});if(error)return json({error:'Unable to claim jobs.'},500);const results=[];for(const job of jobs||[]){let externalDispatchStarted=false;try{const {data:tenant}=await db.from('growth_organizations').select('status').eq('id',job.organization_id).maybeSingle();if(tenant?.status!=='active'){await db.from('growth_jobs').update({status:'queued',run_at:new Date(Date.now()+30*60*1000).toISOString(),locked_at:null,last_error:'Workspace is suspended; job execution paused.'}).eq('id',job.id);results.push({id:job.id,status:'paused_tenant'});continue;}const externalEffectTypes=['publish_content','send_whatsapp','send_whatsapp_template','send_email','send_sms','send_briefing_email'];const mayCallProvider=externalEffectTypes.includes(job.job_type);if(['send_whatsapp','send_whatsapp_template','send_email','send_sms'].includes(job.job_type)){const {data:policyOrg, error:policyError}=await db.from('growth_organizations').select('communication_policy').eq('id',job.organization_id).maybeSingle();if(policyError)throw new Error('SEND_POLICY_UNAVAILABLE: Could not load workspace communication policy.');const channel=job.job_type==='send_email'?'email':job.job_type==='send_sms'?'sms':'whatsapp';const policy=evaluateGrowthSendPolicy(policyOrg?.communication_policy,channel);if(!policy.allowed){const {error:deferError}=await db.from('growth_jobs').update({status:'queued',run_at:new Date(Date.now()+15*60*1000).toISOString(),locked_at:null,last_error:`POLICY_DEFERRED:${policy.reason}`}).eq('id',job.id).eq('organization_id',job.organization_id);if(deferError)throw deferError;results.push({id:job.id,status:'deferred_policy'});continue;}}if(mayCallProvider&&job.job_type!=='send_sms'){const {error:markError}=await db.from('growth_jobs').update({external_effect_started_at:new Date().toISOString()}).eq('id',job.id).eq('organization_id',job.organization_id);if(markError)throw new Error(`EXECUTION_GUARD_UNAVAILABLE: ${markError.message}`);externalDispatchStarted=true;}let jobResult:any;if(job.job_type==='publish_content')jobResult=await publish(db,job);else if(job.job_type==='send_whatsapp')jobResult=await sendWhatsApp(db,job);else if(job.job_type==='send_whatsapp_template')jobResult=await sendWhatsAppTemplate(db,job);else if(job.job_type==='send_email')jobResult=await sendEmail(db,job);else if(job.job_type==='send_briefing_email')jobResult=await sendBriefingEmail(db,job);else if(job.job_type==='send_sms')jobResult=await sendSms(db,job);else throw new Error(`Unsupported job type: ${job.job_type}`);if(jobResult?.pending){const {error:pendingError}=await db.from('growth_jobs').update({status:'queued',run_at:new Date(Date.now()+10000).toISOString(),locked_at:null,attempts:0,last_error:null,external_effect_started_at:null}).eq('id',job.id);if(pendingError)throw new Error(`LOCAL_PROGRESS_PERSIST_FAILED: ${pendingError.message}`);results.push({id:job.id,status:'uploading',progress:{uploadedBytes:jobResult.uploadedBytes,totalBytes:jobResult.totalBytes}});continue;}const {error:completionError}=await db.from('growth_jobs').update({status:'succeeded',completed_at:new Date().toISOString(),last_error:null,external_effect_started_at:null}).eq('id',job.id);if(completionError)throw new Error(`LOCAL_COMPLETION_PERSIST_FAILED: ${completionError.message}`);if(job.job_type==='send_email'&&job.payload?.retention_touchpoint_id){const sentAt=new Date().toISOString();await db.from('growth_retention_touchpoints').update({status:'sent',sent_at:sentAt,provider_message_id:jobResult?.id||null,failure_reason:null,updated_at:sentAt}).eq('id',job.payload.retention_touchpoint_id).eq('organization_id',job.organization_id).eq('job_id',job.id).eq('status','queued');await db.from('growth_lead_activities').insert({organization_id:job.organization_id,lead_id:job.payload.lead_id,activity_type:'email',body:'Approved customer retention email accepted by the provider.',metadata:{retention_touchpoint_id:job.payload.retention_touchpoint_id,job_id:job.id,provider_message_id:jobResult?.id||null}});}if(job.job_type==='send_email'&&job.payload?.review_request_id){const sentAt=new Date().toISOString();await db.from('growth_review_requests').update({status:'sent',sent_at:sentAt,provider_message_id:jobResult?.id||null,updated_at:sentAt}).eq('id',job.payload.review_request_id).eq('organization_id',job.organization_id);await db.from('growth_review_events').insert({organization_id:job.organization_id,request_id:job.payload.review_request_id,event_type:'review_request_sent',status:'success',details:{channel:'email',job_id:job.id,provider_message_id:jobResult?.id||null}});}if(job.job_type==='send_briefing_email'&&job.payload?.schedule_run_id){const {error:receiptError}=await db.from('growth_autonomous_schedule_runs').update({status:'completed',result:{...(job.payload.schedule_result||{}),delivery:{status:'accepted',provider:'resend',providerMessageId:jobResult?.id||null,recipient:job.payload.recipient_email}},completed_at:new Date().toISOString()}).eq('id',job.payload.schedule_run_id).eq('organization_id',job.organization_id);if(receiptError)console.error('Briefing email accepted but schedule receipt update failed.',{jobId:job.id,runId:job.payload.schedule_run_id});}if(job.job_type==='send_email'&&job.payload?.proposal_id){const sentAt=new Date().toISOString();const {data:proposal,error:proposalError}=await db.from('growth_proposals').update({status:'sent',delivery_status:'sent',sent_at:sentAt,delivered_at:sentAt,provider_message_id:jobResult?.id||null,updated_at:sentAt}).eq('id',job.payload.proposal_id).eq('organization_id',job.organization_id).eq('delivery_job_id',job.id).eq('delivery_status','queued').select('id,lead_id,reference_no').maybeSingle();if(proposalError||!proposal){console.error('Proposal email accepted by provider but proposal lifecycle update needs reconciliation.',{jobId:job.id,proposalId:job.payload.proposal_id,error:proposalError?.message});}else{await db.from('growth_lead_activities').insert({organization_id:job.organization_id,lead_id:proposal.lead_id,activity_type:'email',body:`Proposal ${proposal.reference_no} accepted by the email provider.`,metadata:{proposal_id:proposal.id,job_id:job.id,provider_message_id:jobResult?.id||null}});}}results.push({id:job.id,status:'succeeded'});}catch(e){const message=e instanceof Error?e.message:'Job failed';const uncertainExternalOutcome=externalDispatchStarted||message.startsWith('EXECUTION_GUARD_UNAVAILABLE:')||message.startsWith('EXTERNAL_EFFECT_STARTED:');const terminal=uncertainExternalOutcome||job.attempts>=job.max_attempts||message.startsWith('QUOTA_BLOCKED:');const persistedError=uncertainExternalOutcome?`OUTCOME_UNKNOWN_RECONCILIATION_REQUIRED: Provider outcome may be unknown; automatic retry suppressed to prevent duplicate external action. ${message}`:message;await db.from('growth_jobs').update({status:terminal?'failed':'queued',last_error:persistedError.slice(0,2000),run_at:new Date(Date.now()+Math.min(60,Math.pow(2,job.attempts))*60000).toISOString(),locked_at:null}).eq('id',job.id);if(job.job_type==='publish_content'&&job.payload?.content_id){await db.from('growth_content').update({...(terminal?{status:'failed'}:{}),last_publish_error:persistedError.slice(0,2000),updated_at:new Date().toISOString()}).eq('id',job.payload.content_id).eq('organization_id',job.organization_id);await db.from('growth_content_publication_events').insert({organization_id:job.organization_id,content_id:job.payload.content_id,social_account_id:job.payload.social_account_id||null,job_id:job.id,platform:String(job.payload.platform||'unknown'),event_type:'failed',message:persistedError.slice(0,1500),metadata:{terminal,externalOutcomeUncertain:uncertainExternalOutcome}});}if(job.job_type==='send_email'&&job.payload?.retention_touchpoint_id&&terminal)await db.from('growth_retention_touchpoints').update({status:'failed',failure_reason:persistedError.slice(0,1500),updated_at:new Date().toISOString()}).eq('id',job.payload.retention_touchpoint_id).eq('organization_id',job.organization_id).eq('job_id',job.id).eq('status','queued');if(job.job_type==='send_email'&&job.payload?.review_request_id&&terminal)await db.from('growth_review_requests').update({status:'failed',failure_reason:persistedError.slice(0,1500),updated_at:new Date().toISOString()}).eq('id',job.payload.review_request_id).eq('organization_id',job.organization_id);if(job.job_type==='send_briefing_email'&&job.payload?.schedule_run_id&&terminal)await db.from('growth_autonomous_schedule_runs').update({status:'failed',error_message:persistedError.slice(0,1500),result:{...(job.payload.schedule_result||{}),delivery:{status:uncertainExternalOutcome?'outcome_unknown':'failed',recipient:job.payload.recipient_email}}}).eq('id',job.payload.schedule_run_id).eq('organization_id',job.organization_id);if(job.job_type==='send_email'&&job.payload?.proposal_id&&terminal)await db.from('growth_proposals').update({delivery_status:'failed',updated_at:new Date().toISOString()}).eq('id',job.payload.proposal_id).eq('organization_id',job.organization_id).eq('delivery_job_id',job.id).eq('delivery_status','queued');if(job.job_type==='send_sms'&&job.payload?.sms_message_id){await db.from('growth_sms_messages').update({status:uncertainExternalOutcome?'outcome_unknown':terminal?'failed':'queued',error_message:persistedError.slice(0,500),updated_at:new Date().toISOString()}).eq('id',job.payload.sms_message_id).eq('organization_id',job.organization_id);}results.push({id:job.id,status:terminal?'failed':'retry',error:message});}}let workflowResults:any[]=[];try{workflowResults=await processWorkflowRuns(db);}catch(e){workflowResults=[{status:'error',error:e instanceof Error?e.message:'Workflow runner failed'}];}return json({claimed:(jobs||[]).length,results,workflowRuns:workflowResults,autonomousSchedules});}
